"""Mechanics of the published sparse-edit reader, independently generated bytes."""
import hashlib
import importlib.util
import json
import struct
from pathlib import Path

import numpy as np
import pytest
import torch
from safetensors.torch import save_file

HERE = Path(__file__).resolve().parents[1] / "qualification/wsp_case_study"


def source(name):
    spec = importlib.util.spec_from_file_location("wsp_test_" + name, HERE / (name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def raw_sha(value):
    return hashlib.sha256(value.contiguous().view(torch.uint8).numpy().tobytes()).hexdigest()


def test_prompt_tensor_handles_hf_batch_encoding_and_direct_tensor():
    from transformers.tokenization_utils_base import BatchEncoding

    value = torch.tensor([[1, 2, 3]], dtype=torch.int64)
    extract = source("worker").prompt_tensor
    assert extract(value) is value
    assert extract(BatchEncoding({"input_ids": value})) is value
    with pytest.raises(ValueError, match="int64"):
        extract(value.float())


def test_presence_penalty_and_sampling_use_own_generated_history():
    choose = source("worker").choose_token
    logits = torch.tensor([[2., 1., 0.]])
    seen = torch.tensor([False, False, False])
    policy = {"kind": "think35", "temperature": .6, "presence_penalty": 1.5, "top_k": 1, "top_p": .95}
    assert choose(logits, seen, policy, torch.Generator().manual_seed(0)) == 0
    seen[0] = True
    assert choose(logits, seen, policy, torch.Generator().manual_seed(0)) == 1
    assert choose(logits, seen, {"kind": "greedy"}, torch.Generator()) == 0


def test_saved_local_error_retains_small_response_error_and_invalid_instruments():
    error = source("audit_saved").numerical_error
    # A small endpoint residual can be substantial relative to the edit itself.
    assert error([100.01], [100.])["relative_rms"] == pytest.approx(.0001)
    assert error([.02], [.01])["relative_rms"] == pytest.approx(1.)
    assert error([0.], [0.])["relative_rms"] is None
    with pytest.raises(ValueError, match="geometry"):
        error([1., 2.], [1.])
    with pytest.raises(ValueError, match="values"):
        error([float("nan")], [1.])


def test_report_writer_accepts_nested_readonly_sampling_metadata(tmp_path):
    from types import MappingProxyType

    value = MappingProxyType({"sampling": MappingProxyType({"seed": 2, "top_p": .95})})
    path = tmp_path / "report.json"
    source("worker").save(path, value)
    assert json.loads(path.read_text()) == {"sampling": {"seed": 2, "top_p": .95}}


def test_reconstruct_exact_sparse_bf16_and_reject_duplicate_support(tmp_path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    before = torch.arange(16, dtype=torch.float32).reshape(4, 4).to(torch.bfloat16)
    edited = before.clone()
    edited[0, 0], edited[2, 3] = -0., -3.25
    save_file({"D": before}, "original.safetensors")
    metadata = {"tensors": [{"name": "D", "form": "sparse", "base_sha256": raw_sha(before),
                             "edited_sha256": raw_sha(edited)}]}
    Path("edit-manifest.json").write_text(json.dumps(metadata))
    indices = np.array([0, 11], dtype=np.int32)
    values = edited.view(torch.uint16).numpy().reshape(-1)[indices]
    np.savez("edit.npz", t0_idx=indices, t0_val=values)
    original, reconstructed = source("worker").reconstruct(Path("original.safetensors"))
    assert raw_sha(original["D"]) == raw_sha(before)
    assert raw_sha(reconstructed["D"]) == raw_sha(edited)
    np.savez("edit.npz", t0_idx=np.array([0, 0]), t0_val=values)
    with pytest.raises(ValueError, match="support"):
        source("worker").reconstruct(Path("original.safetensors"))


def test_parameter_retrieval_binds_original_header_and_full_file(tmp_path):
    value = torch.tensor([[1., -0.], [3., 4.]], dtype=torch.bfloat16)
    path = tmp_path / "model.safetensors"
    save_file({"D": value}, path)
    raw = path.read_bytes()
    length = struct.unpack("<Q", raw[:8])[0]
    header_raw = raw[8:8 + length]
    header = json.loads(header_raw)
    manifest = {"checkpoint_files": {path.name: {"sha256": hashlib.sha256(raw).hexdigest()}},
        "archive_headers": {path.name: {"sha256": hashlib.sha256(header_raw).hexdigest()}},
        "tensors": {"D": {"file": path.name, "archive_entry": header["D"], "sha256": raw_sha(value)}}}
    retrieve = source("retrieve_weights").retrieve
    assert retrieve(manifest, tmp_path)["tensors"] == 1
    retrieve(manifest, tmp_path, tmp_path / "restored.safetensors")
    from safetensors import safe_open
    with safe_open(tmp_path / "restored.safetensors", framework="pt") as archive:
        assert raw_sha(archive.get_tensor("D")) == raw_sha(value)
    path.write_bytes(raw[:-1] + b"x")
    with pytest.raises(ValueError, match="checkpoint file"):
        retrieve(manifest, tmp_path)
